float hash(vec3 p){p=fract(p*0.3183099+0.1);p*=17.0;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
float vnoise(vec3 x){vec3 i=floor(x),f=fract(x);f=f*f*(3.0-2.0*f);
 return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
float fbm(vec3 p){return vnoise(p)*0.55+vnoise(p*2.1)*0.28+vnoise(p*4.3)*0.17;}
float smin(float a,float b,float k){float h=clamp(0.5+0.5*(b-a)/k,0.0,1.0);return mix(b,a,h)-k*h*(1.0-h);}
float sEll(vec3 p,vec3 r){float k0=length(p/r),k1=length(p/(r*r));return k0*(k0-1.0)/k1;}
float sTap(vec3 p,vec3 a,vec3 b,float ra,float rb){vec3 pa=p-a,ba=b-a;float h=clamp(dot(pa,ba)/dot(ba,ba),0.0,1.0);return length(pa-ba*h)-mix(ra,rb,h);}
float sRBox(vec3 p,vec3 b,float r){vec3 q=abs(p)-b+r;return length(max(q,0.0))+min(max(q.x,max(q.y,q.z)),0.0)-r;}
float sOBox(vec3 p,vec3 a,vec3 b,vec3 sd,vec2 hw){vec3 u=b-a;float L=length(u);u/=L;vec3 v=normalize(sd-u*dot(sd,u));vec3 w=cross(u,v);vec3 q=p-a;
 vec3 l=vec3(dot(q,v),dot(q,u)-L*0.5,dot(q,w));vec3 d=abs(l)-vec3(hw.x,L*0.5,hw.y);return length(max(d,0.0))+min(max(d.x,max(d.y,d.z)),0.0);}
// 頭（頭の中心から見た位置）
float sHead(vec3 h){
 vec3 q=h;q.x*=1.0+q.y*0.10;                      // 下（あご）を少し広く
 float d=mix(sRBox(q,vec3(0.39,0.41,0.33),0.27),sEll(q,vec3(0.42,0.44,0.37)),0.62);
 for(int s=0;s<2;s++){float sg=s==0?-1.0:1.0;vec3 e=vec3(h.x*sg,h.y,h.z);
  d=smin(d,sEll(e-vec3(0.17,0.15,0.29),vec3(0.14,0.055,0.07)),0.06);
  d=smin(d,sEll(e-vec3(0.22,-0.12,0.24),vec3(0.13,0.1,0.1)),0.08);
  vec3 ep=e;ep.z=(ep.z+0.04)*2.4;float ear=sTap(ep,vec3(0.32,0.04,-0.05),vec3(0.84,0.24,-0.26),0.15,0.014)/2.0;
  vec3 ip=e-vec3(0.0,0.0,0.035);ip.z=(ip.z+0.04)*2.4;float inr=sTap(ip,vec3(0.42,0.07,-0.05),vec3(0.78,0.23,-0.26),0.085,0.008)/2.0;
  ear=max(ear,-inr);d=smin(d,ear,0.05);}
 return d;}
