float sHand(vec3 p,int side){vec3 w=side==0?J[5]:J[8];float d=sEll(p-w,vec3(0.135,0.12,0.13));
 for(int f=0;f<4;f++){vec3 a,b;if(side==0){a=J[17+f*2];b=J[18+f*2];}else{a=J[25+f*2];b=J[26+f*2];}d=smin(d,sTap(p,a,b,0.05,0.042),0.03);}return d;}
