 for(int s=0;s<2;s++){vec3 a=s==0?J[11]:J[14];vec3 t=s==0?J[15]:J[16];vec3 fw=normalize(vec3(t.x-a.x,0.0,t.z-a.z));vec3 sd=vec3(fw.z,0.0,-fw.x);
  for(int k=0;k<3;k++){float o=float(k)-1.0;vec3 q=vec3(t.x,0.045,t.z)+sd*o*0.07-fw*abs(o)*0.025;c=min(c,sEll(p-q,vec3(0.045,0.04,0.05)));}}
