vec3 lin(vec3 c){return pow(c,vec3(2.2));}
vec4 charCol(vec3 p,vec3 n,float m){vec3 c;float sp=0.08;
 vec3 hp=HR*(p-J[2]);
 if(m<1.5){vec3 lp=p-J[0];float f1=fbm(lp*5.0),f2=fbm(lp*13.0+7.0);c=lin(SKIN[0])*(0.82+0.32*f1)*(0.93+0.12*f2);
  c=mix(c,c*vec3(0.78,0.9,0.62),smoothstep(0.55,0.75,fbm(lp*2.4+3.0))*0.6);
  if(hasFace>0.5&&length(hp)<0.62&&abs(hp.x)<0.45){vec3 hn=HR*n;float fz=smoothstep(0.05,0.3,hn.z);
   vec2 fu=vec2(hp.x/0.84+0.5,0.5-hp.y/0.86);if(fu.x>0.0&&fu.x<1.0&&fu.y>0.0&&fu.y<1.0){vec4 tx=texture2D(face,vec2((fu.x+FI[0])/8.0,fu.y));float a=tx.a*fz;
    c=mix(c,lin(tx.rgb),a);float glow=a*step(0.9,tx.r)*step(tx.b,0.45)*step(0.3,tx.g);c+=lin(tx.rgb)*glow*1.6;}}}
 else if(m<2.5){c=lin(vec3(0.92,0.86,0.70));sp=0.15;}
 else if(m<3.5){vec3 lp=TR*(p-J[0]);c=lin(CLOTH[0])*(0.72+0.4*fbm(vec3(lp.x*9.0,lp.y*30.0,lp.z*9.0)));sp=0.02;}
 else if(m<4.5){c=lin(vec3(0.42,0.26,0.13))*(0.8+0.3*fbm(p*vec3(25.0,4.0,25.0)));sp=0.1;}
 else if(m<5.5){c=lin(vec3(0.5,0.53,0.58))*(0.8+0.3*fbm(p*18.0));sp=0.55;
  if(tool<1.5){float k=dot(p-J[34],normalize(J[35]-J[34]))/length(J[35]-J[34]);c=mix(c,lin(vec3(0.62,0.06,0.06)),step(0.76,k)*0.9);}}
 else c=lin(vec3(0.42,0.36,0.30))*(0.8+0.4*fbm(p*30.0));

 if(m>6.5&&m<7.5){c=lin(vec3(0.56,0.58,0.63))*(0.75+0.35*fbm(p*14.0));sp=0.7;}
 if(m>7.5&&m<8.5){c=lin(vec3(0.52,0.33,0.17))*(0.7+0.4*fbm(p*vec3(3.0,18.0,3.0)));sp=0.05;}
 if(m>8.5&&m<9.5){c=lin(vec3(0.95,0.72,0.28))*(0.85+0.2*fbm(p*20.0));sp=0.9;}
