 if(m>11.5&&m<12.5){c=lin(vec3(0.9,0.86,0.74))*(0.85+0.2*fbm(p*16.0));sp=0.3;}
 return vec4(c,sp);}

vec3 toC(vec3 p,vec3 o,float r){vec3 q=p-o;float c=cos(r),s=sin(r);return vec3(c*q.x-s*q.z,q.y,s*q.x+c*q.z);}
vec3 frC(vec3 n,float r){float c=cos(r),s=sin(r);return vec3(c*n.x-s*n.z,n.y,s*n.x+c*n.z);}
float sBox(vec3 p,vec3 b){vec3 q=abs(p)-b;return length(max(q,0.0))+min(max(q.x,max(q.y,q.z)),0.0);}
// 洞窟：岩をくりぬいた広間。奥に坑道の入口（木の支え）、左に訓練台、右に寝わら、手前に鉱石の岩
float caveIn(vec2 q){vec2 d=abs(q)-vec2(3.05,2.05)+1.0;float r=length(max(d,0.0))+min(max(d.x,d.y),0.0)-1.0;
 r+=(vnoise(vec3(q*1.1,0.0))-0.5)*0.75+(vnoise(vec3(q*2.7,3.0))-0.5)*0.25;
 return r;}
vec2 room(vec3 p){return vec2(1e3,0.0);}
vec3 scene(vec3 p){
 vec2 r=PASS>2.5?vec2(1e3,0.0):room(p);vec3 o=vec3(r,0.0);vec3 q;float bb;
 if(PASS<0.5||PASS>2.5){ q=toC(p,OC[0],RC[0])/(CS*SCL[0]);if(LIE[0]>0.5)q=vec3(0.45-q.y,q.x,q.z);bb=(length(q-vec3(0,0.90,0))-1.55)*CS*SCL[0];if(bb<0.3){vec2 b=body(q);b.x*=CS*SCL[0];if(b.x<o.x)o=vec3(b,1.0);}else if(bb<o.x)o=vec3(bb,0.0,-1.0);}
 return o;}
float mapd(vec3 p){return scene(p).x;}
vec3 nrm(vec3 p){vec2 e=vec2(0.0015,-0.0015);return normalize(e.xyy*mapd(p+e.xyy)+e.yyx*mapd(p+e.yyx)+e.yxy*mapd(p+e.yxy)+e.xxx*mapd(p+e.xxx));}
float ao(vec3 p,vec3 n){float o=0.0,s=1.0;for(int i=1;i<6;i++){float h=0.02+0.08*float(i);o+=(h-mapd(p+n*h))*s;s*=0.72;}return clamp(1.0-2.0*o,0.0,1.0);}
float shadow(vec3 ro,vec3 rd){float r=1.0,t=0.03;for(int i=0;i<36;i++){float h=mapd(ro+rd*t);r=min(r,8.0*h/t);t+=clamp(h,0.03,0.3);if(r<0.005||t>6.0)break;}return clamp(r,0.0,1.0);}

uniform vec3 G0;uniform float GS;uniform vec2 GN;uniform float WW;
void main(){float idx=floor(gl_FragCoord.y)*WW+floor(gl_FragCoord.x);float k=floor(idx/(GN.x*GN.y));float r=idx-k*GN.x*GN.y;float j=floor(r/GN.x);float i=r-j*GN.x;
